document.querySelector('.menu-button')?.addEventListener('click',e=>{const n=document.querySelector('.primary-nav');const open=n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));document.body.classList.toggle('menu-open',open)});const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');o.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>o.observe(e));